	 ('Gân bò hầm đậu phộng ít dầu','[''Thịt nạc'']','Việt Nam','[''gân bò'', ''đậu phộng'', ''collagen'', ''protein'']','Gân bò giàu collagen hỗ trợ tái tạo mạch máu và thần kinh, hầm với đậu phộng tăng vị béo tự nhiên.','30 phút','90 phút','120 phút',2,'1 phần (~300g)','thấp',2.50,225,11.50,3.50,0.20,48.00,358.00,8.50,2.50,1.50,0.20,20.50,418.00,215.00,38.00,0.20,32.00,2.20,0.30,true,true,false,true,true,true,'Collagen hỗ trợ phục hồi mạch máu thần kinh; TĐ thai kỳ hạn chế','1 phần nhỏ/bữa','TĐ thai kỳ hạn chế','[''bữa trưa'', ''bữa tối'']','khó','trung bình','250g gân bò (làm mềm trước)
