	 ('Thịt heo nạc rim nghệ','[''Thịt nạc'']','Việt Nam','[''thịt heo'', ''nghệ'', ''curcumin'', ''ít đường'']','Curcumin từ nghệ kháng viêm mạnh, rim ít đường giữ vị đậm đà tự nhiên.','15 phút','25 phút','40 phút',2,'1 phần (~300g)','thấp',1.80,172,7.50,2.50,0.10,55.00,358.00,5.50,0.30,2.00,0.30,22.50,398.00,195.00,30.00,0.30,18.00,1.80,0.20,true,true,true,true,true,true,'Curcumin kháng viêm - tốt mọi biến chứng TĐ','1 phần/bữa','Không có','[''bữa trưa'', ''bữa tối'']','dễ','thấp','200g thịt nạc heo
